class TestServiceStatus:
    """Test ServiceStatus enum behavior."""

    def test_enum_values(self):
        """Verify all enum values exist."""
        assert ServiceStatus.HEALTHY.value == "healthy"
        assert ServiceStatus.DEGRADED.value == "degraded"
        assert ServiceStatus.UNRESPONSIVE.value == "unresponsive"
        assert ServiceStatus.RESTARTING.value == "restarting"
        assert ServiceStatus.STOPPED.value == "stopped"

    def test_enum_membership(self):
        """Verify enum membership checks."""
        assert "healthy" in [s.value for s in ServiceStatus]
        assert "unknown" not in [s.value for s in ServiceStatus]

    def test_enum_comparison(self):
        """Verify enum comparison works."""
        assert ServiceStatus.HEALTHY == ServiceStatus.HEALTHY
        assert ServiceStatus.HEALTHY != ServiceStatus.DEGRADED

    def test_enum_from_string(self):
        """Verify string to enum conversion."""
        assert ServiceStatus("healthy") == ServiceStatus.HEALTHY
        with pytest.raises(ValueError):
            ServiceStatus("unknown")


