class TestHealthCheck:
    """Test health check logic."""

    @pytest.mark.asyncio
    async def test_health_check_success(self, service_monitor: ServiceMonitor, mock_http_response):
        """Verify successful health check returns healthy status."""
        with patch('urllib.request.urlopen', return_value=mock_http_response) as mock_urlopen:
            result = await service_monitor.check_health()
            assert result == HealthCheckResult.HEALTHY
