class TestRestartLogic:
    """Test restart orchestration."""

    @pytest.mark.asyncio
    async def test_restart_service_success(self, service_monitor: ServiceMonitor, mock_subprocess):
        """Verify successful restart."""
        result = await service_monitor.restart_service()
        assert result is True
        assert service_monitor.restart_attempts == 1
        assert service_monitor.status == ServiceStatus.RESTARTING
        mock_subprocess.assert_called_once_with(
            service_monitor.config.restart_command,
            capture_output=True,
            timeout=30
        )

    @pytest.mark.asyncio
    async def test_restart_service_failure(self, service_monitor: ServiceMonitor):
        """Verify restart failure handling."""
        with patch('subprocess.run', side_effect=subprocess.CalledProcessError(1, "restart")):
            result = await service_monitor.restart_service()
            assert result is False
            assert service_monitor.restart_attempts == 1

    @pytest.mark.asyncio
    async def test_restart_service_timeout(self, service_monitor: ServiceMonitor):
        """Verify restart timeout handling."""
        with patch('subprocess.run', side_effect=subprocess.TimeoutExpired("restart", 30)):
            result = await service_monitor.restart_service()
            assert result is False

    @pytest.mark.asyncio
    async def test_restart_cooldown_respected(self, service_monitor: ServiceMonitor):
        """Verify restart cooldown is respected."""
        service_monitor.last_restart_time = datetime.now(timezone.utc)
        service_monitor.config.restart_cooldown = 60  # 60 seconds cooldown
        
        with patch('subprocess.run') as mock_run:
            result = await service_monitor.restart_service()
            assert result is False  # Should not restart due to cooldown
            mock_run.assert_not_called()

    @pytest.mark.asyncio
    async def test_max_restart_attempts_exceeded(self, service_monitor: ServiceMonitor):
        """Verify max restart attempts limit."""
        service_monitor.restart_attempts = service_monitor.config.max_restart_attempts
        
        with patch('subprocess.run') as mock_run:
            result = await service_monitor.restart_service()
            assert result is False
            assert service_monitor.status == ServiceStatus.STOPPED
            mock_run.assert_not_called()

    @pytest.mark.asyncio
    async def test_restart_updates_status(self, service_monitor: ServiceMonitor, mock_subprocess):
        """Verify status transitions during restart."""
        assert service_monitor.status == ServiceStatus.STOPPED
        
        await service_monitor.restart_service()
        assert service_monitor.status == ServiceStatus.RESTARTING
        
        # After successful restart, status should be healthy
        await asyncio.sleep(0.1)  # Allow async status update
        assert service_monitor.status == ServiceStatus.HEALTHY

    @pytest.mark.asyncio
    async def test_restart_concurrent_safety(self, service_monitor: ServiceMonitor):
        """Verify concurrent restart attempts are serialized."""
        with patch('subprocess.run') as mock_run:
            mock_run.return_value = MagicMock(returncode=0)
            
            # Attempt multiple restarts concurrently
            tasks = [service_monitor.restart_service() for _ in range(3)]
            results = await asyncio.gather(*tasks)
            
            # Only first should succeed, others should be blocked by semaphore
            assert results.count(True) == 1
            assert results.count(False) == 2
            assert mock_run.call_count == 1


