class TestIntegration:
    """Integration tests for self-healing infrastructure."""

    @pytest.mark.asyncio
    async def test_self_healing_loop(self, self_healing_manager: SelfHealingManager, valid_service_config: ServiceConfig):
        """Verify the self-healing monitoring loop."""
        await self_healing_manager.add_service(valid_service_config)
        
        # Mock health checks to simulate failure then recovery
        health_results = [
            HealthCheckResult.HEALTHY,
            HealthCheckResult.HEALTHY,
            HealthCheckResult.UNRESPONSIVE,
            HealthCheckResult.HEALTHY,
            HealthCheckResult.HEALTHY
        ]
        
        with patch.object(
            self_healing_manager.monitors[valid_service_config.name],
            'check_health',
            side_effect=health_results
        ), patch.object(
            self_healing_manager.monitors[valid_service_config.name],
            'restart_service',
            return_value=True
        ):
            # Run monitoring loop for a few iterations
            for _ in range(5):
                await self_healing_manager.monitor_loop(valid_service_config.name)
                await asyncio.sleep(0.01)
            
            # Service should be healthy after recovery
            status = await self_healing_manager.get_service_status(valid_service_config.name)
            assert status == ServiceStatus.HEALTHY

    @pytest.mark.asyncio
    async def test_multiple_services_healing(self, self_healing_manager: SelfHealingManager):
        """Verify multiple services can be healed independently."""
        configs = [
            ServiceConfig(
                name=f"service_{i}",
                health_endpoint=f"http://localhost:{8000 + i}/health",
                restart_command=["systemctl", "restart", f"swarm-{i}"],
                port=8000 + i
            )
            for i in range(3)
        ]
        
        for config in configs:
            await self_healing_manager.add_service(config)
        
        # Simulate all services failing
        for config in configs:
            with patch.object(
                self_healing_manager.monitors[config.name],
                'check_health',
                return_value=HealthCheckResult.UNRESPONSIVE
            ), patch.object(
                self_healing_manager.monitors[config.name],
                'restart_service',
                return_value=True
            ):
                healed = await self_healing_manager.heal_service(config.name)
                assert healed is True

    @pytest.mark.asyncio
    async def test_persistence_across_restarts(self, self_healing_manager: SelfHealingManager, valid_service_config: ServiceConfig, tmp_path):
        """Verify state persistence across manager restarts."""
        # Add service and modify state
        await self_healing_manager.add_service(valid_service_config)
        self_healing_manager.monitors[valid_service_config.name].restart_attempts = 2
        
        # Save state
        state_file = tmp_path / "state.json"
        await self_healing_manager.save_state(str(state_file))
        
        # Create new manager and load state
        new_manager = SelfHealingManager()
        await new_manager.load_state(str(state_file))
        
        # Verify state was restored
        assert valid_service_config.name in new_manager.monitors
        assert new_manager.monitors[valid_service_config.name].restart_attempts == 2


