class TestPerformance:
    """Performance and stress tests."""

    @pytest.mark.asyncio
    async def test_high_frequency_health_checks(self, service_monitor: ServiceMonitor):
        """Verify performance under high frequency health checks."""
        with patch('urllib.request.urlopen') as mock_urlopen:
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "healthy"}'
            mock_urlopen.return_value = mock_response
            
            # Run 100 health checks rapidly
            start_time = time.time()
            tasks = [service_monitor.check_health() for _ in range(100)]
            results = await asyncio.gather(*tasks)
            end_time = time.time()
            
            # All should succeed
            assert all(r == HealthCheckResult.HEALTHY for r in results)
            # Should complete within reasonable time (adjust based on expectations)
            assert end_time - start_time < 10.0

    @pytest.mark.asyncio
    async def test_memory_usage(self, self_healing_manager: SelfHealingManager):
        """Verify memory usage with many services."""
        import tracemalloc
        
        tracemalloc.start()
        
        # Add 100 services
        for i in range(100):
            config = ServiceConfig(
                name=f"service_{i}",
                health_endpoint=f"http://localhost:{8000 + i}/health",
                restart_command=["systemctl", "restart", f"swarm-{i}"],
                port=8000 + i
            )
            await self_healing_manager.add_service(config)
        
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        
        # Memory should be reasonable (adjust threshold as needed)
        assert peak < 50 * 1024 * 1024  # Less than 50 MB


