# Race Condition Tests
# ============================================================================

class TestRaceConditions:
    """Test race condition prevention."""

    @pytest.mark.asyncio
    async def test_concurrent_health_and_restart(self, service_monitor: ServiceMonitor):
        """Verify health check and restart don't race."""
        with patch('urllib.request.urlopen') as mock_urlopen, \
             patch('subprocess.run') as mock_run:
            
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "healthy"}'
            mock_urlopen.return_value = mock_response
            mock_run.return_value = MagicMock(returncode=0)
            
            # Run health check and restart concurrently
            async def health_check():
                return await service_monitor.check_health()
            
            async def restart():
                return await service_monitor.restart_service()
            
            results = await asyncio.gather(health_check(), restart())
            
            # Both should complete without deadlock
            assert results[0] == HealthCheckResult.HEALTHY
            assert results[1] is True

    @pytest.mark.asyncio
    async def test_lock_contention(self, service_monitor: ServiceMonitor):
        """Verify lock contention is handled."""
        with patch('urllib.request.urlopen') as mock_urlopen:
            mock_response = MagicMock()
            mock_response.status = 200
            mock_response.read.return_value = b'{"status": "healthy"}'
            mock_urlopen.return_value = mock_response
            
            # Create many concurrent tasks
            tasks = []
            for _ in range(50):
                tasks.append(service_monitor.check_health())
            
            # All should complete without deadlock
            results = await asyncio.gather(*tasks)
            assert all(r == HealthCheckResult.HEALTHY for r in results)


