class TestCleanup:
    """Test resource cleanup."""

    @pytest.mark.asyncio
    async def test_monitor_cleanup(self, service_monitor: ServiceMonitor):
        """Verify monitor cleanup releases resources."""
        # Add some state
        service_monitor.restart_attempts = 3
        service_monitor.last_heartbeat = datetime.now(timezone.utc)
        
        await service_monitor.cleanup()
        
        assert service_monitor.restart_attempts == 0
        assert service_monitor.last_heartbeat is None
        assert service_monitor.status == ServiceStatus.STOPPED

    @pytest.mark.asyncio
    async def test_manager_cleanup(self, self_healing_manager: SelfHealingManager, valid_service_config: ServiceConfig):
        """Verify manager cleanup releases all resources."""
        await self_healing_manager.add_service(valid_service_config)
        await self_healing_manager.cleanup()
        
        assert len(self_healing_manager.monitors) == 0


